export function createPreferencesUI(ctx){
  const {state,boot,esc,icon,btn,api,persist,render,openModal,closeModal,go,toast,saveForm,autoIntroduce}=ctx;
  const $=s=>document.querySelector(s);
  function partyField(){return `<div class="field"><span class="field-label">和谁一起？</span><div class="chips">${[['solo','独自'],['couple','两人'],['family','亲子']].map(([id,label])=>btn('party',label,`chip ${(state.preferences.party||'solo')===id?'active':''}`,`type="button" data-party="${id}" aria-pressed="${(state.preferences.party||'solo')===id}"`)).join('')}</div></div>`;}
  function profile(){const p=state.preferences;return `<div class="drawer-content"><div class="eyebrow">MAKE IT YOURS</div><h2>想怎么度过？</h2><form id="profile-form">${partyField()}<div class="field"><span class="field-label">这次想做什么？</span><div class="chips">${[['explore','看空间'],['relax','放松'],['food','吃点喝点'],['family','一起发现']].map(([id,label])=>btn('style',label,`chip ${p.style===id?'active':''}`,`type="button" data-style="${id}" aria-pressed="${p.style===id}"`)).join('')}</div></div><div class="field"><span class="field-label">有多少时间？</span><div class="chips">${[[30,'半小时'],[60,'1小时'],[120,'2小时'],[180,'3小时'],[240,'半天']].map(([id,label])=>btn('duration',label,`chip ${p.minutes===id?'active':''}`,`type="button" data-minutes="${id}" aria-pressed="${p.minutes===id}"`)).join('')}</div></div><div class="form-row"><label class="field"><span class="field-label">日期</span><input name="date" type="date" required value="${esc(p.date)}"></label><label class="field"><span class="field-label">从几点开始</span><input name="start" type="time" required value="${esc(p.start)}"></label></div><label class="check"><input type="checkbox" name="noExtraSpend" ${p.noExtraSpend?'checked':''}><span>暂不安排额外消费</span></label><div id="profile-feedback"></div><button class="primary wide" type="submit">更新我的推荐 ${icon('arrow')}</button></form></div>`;}
  async function applyProfile(){saveForm();try{const result=await api('/api/discovery',{preferences:state.preferences});state.discovery=result.discovery;state.journey.manual=false;state.journey.paused=false;persist();closeModal(false);go('discover');autoIntroduce();}catch(e){const feedback=$('#profile-feedback');if(feedback)feedback.innerHTML=`<div class="error-box" role="alert">${esc(e.message)}</div>`;}}
  function outing(){const p=state.liveResult?.items.find(x=>x.id===state.outingChoice);if(!p)return `<div class="drawer-content"><p>请先选择查询结果里的地点。</p></div>`;return `<div class="drawer-content"><div class="eyebrow">OUTSIDE, THEN BACK</div><h2>留一段外出时间</h2><p>${esc(p.name)}</p><form id="outing-form"><label class="field"><span class="field-label">想停留多久？</span><select name="visitMinutes">${[30,45,60,90].map(m=>`<option value="${m}">${m}分钟</option>`).join('')}</select></label><label class="field"><span class="field-label">每程交通先留多少时间？</span><select name="travelMinutes">${[15,30,45,60].map(m=>`<option value="${m}" ${m===30?'selected':''}>${m}分钟</option>`).join('')}</select></label><p class="note">会同时预留去程和返程。这里由你估算，不是实时路程。</p><label class="check"><input type="checkbox" name="acknowledged"><span>这是我的时间预留；出发前，我会自行了解地点开放、消费和实际交通。</span></label><div id="outing-feedback"></div><button type="submit" class="primary wide">加入规划，再看看时间 ${icon('arrow')}</button></form></div>`;}
  function detail(p){const o=p.outing;return `<div class="drawer-content"><div class="eyebrow">OUTSIDE THE HOTEL</div><h2>${esc(p.name)}</h2><p>${esc(o.poi.address||o.poi.description||'地点来自飞猪查询。')}</p><div class="outing-budget"><span>去程预留 ${o.travelMinutes}′</span><span>停留 ${o.visitMinutes}′</span><span>返程预留 ${o.travelMinutes}′</span></div><p class="note">这 ${o.totalMinutes} 分钟由你自行预留，未验证营业、消费及实际交通，也没有预订。不在酒店内部示意地图中指路。</p>${o.poi.link?`<a class="source-link" href="${esc(o.poi.link)}" target="_blank" rel="noreferrer">查看飞猪地点详情 ↗</a>`:''}<button class="secondary wide" data-action="nearby">重新选择周边地点</button></div>`;}
  async function saveOuting(form){const data=new FormData(form);try{const r=await api('/api/outing',{poiId:state.outingChoice,visitMinutes:Number(data.get('visitMinutes')),travelMinutes:Number(data.get('travelMinutes')),acknowledged:data.has('acknowledged')});state.outing=r.outing;state.plan=r.plan;state.preferences.includeOutside=true;boot.places=[...boot.places.filter(p=>p.id!=='outside'),r.place];persist();closeModal(false);openModal('planner');}catch(e){const feedback=$('#outing-feedback');if(feedback)feedback.innerHTML=`<div class="error-box" role="alert">${esc(e.message)}</div>`;}}
  async function handle(action,id){
    if(action==='select-outing'){state.outingChoice=id;openModal('outing');return true;}
    if(action==='clear-outing'){try{const r=await api('/api/outing',{clear:true});state.outing=null;state.plan=r.plan;state.preferences.includeOutside=false;state.favorites=state.favorites.filter(x=>x!=='outside');boot.places=boot.places.filter(x=>x.id!=='outside');persist();closeModal(false);render();toast('已移除外出候选，其他安排保留');}catch(e){toast(e.message);}return true;}
    return false;
  }
  return {partyField,profile,outing,detail,applyProfile,saveOuting,handle};
}
